#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/wait.h>
int main(void) {
    setvbuf(stdout, NULL, _IONBF, 0);        /* unbuffered: no duplicated output after fork */
    pid_t child[3];
    for (int i = 0; i < 3; i++) {
        pid_t pid = fork();
        if (pid < 0) { perror("fork"); exit(1); }
        if (pid == 0) {                       /* child */
            printf("Child %d (PID %d) stopping itself\n", i + 1, getpid());
            raise(SIGSTOP);                  /* = kill(getpid(), SIGSTOP) */
            printf("Child %d (PID %d) continued, exiting\n", i + 1, getpid());
            exit(0);
        }
        child[i] = pid;                       /* parent */
        int status;
        waitpid(pid, &status, WUNTRACED);     /* returns once the child is STOPPED */
        if (WIFSTOPPED(status))
            printf("Parent: child %d stopped\n", pid);
    }
    for (int i = 0; i < 3; i++)
        kill(child[i], SIGCONT);              /* resume everyone */
    for (int i = 0; i < 3; i++)
        waitpid(child[i], NULL, 0);           /* reap all: no zombies */
    printf("Parent: all children terminated, exiting\n");
    return 0;
}

