#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
long value = 0;                                     /* shared */
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
void *factorial(void *arg) {
    int n = atoi((char *)arg); long f = 1;
    for (int i = 2; i <= n; i++) f *= i;
    pthread_mutex_lock(&lock);   value += f;   pthread_mutex_unlock(&lock);
    return NULL;
}
void *sum_to_n(void *arg) {
    int n = atoi((char *)arg); long s = 0;
    for (int i = 1; i <= n; i++) s += i;
    pthread_mutex_lock(&lock);   value += s;   pthread_mutex_unlock(&lock);
    return NULL;
}
int main(int argc, char *argv[]) {
    if (argc != 3) { printf("Usage: %s <n1> <n2>\n", argv[0]); return 1; }
    pthread_t t1, t2;
    pthread_create(&t1, NULL, factorial, argv[1]);
    pthread_create(&t2, NULL, sum_to_n,    argv[2]);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    printf("value = %ld\n", value);                 /* e.g. ./a.out 5 4 -> 120 + 10 = 130 */
    return 0;
}
/* compile: gcc prog.c -o prog -pthread */

